with base as (select *, cast(credit_limit as int) credit_limit_int, if(is_active, 'Yes', 'No') is_active_label from customers where city is not null), metrics as (select *, corr(age, credit_limit) over (partition by segment) corr_age_credit_limit, avg(credit_limit) over (partition by country order by credit_limit_int, id rows between 2 preceding and 1 preceding) credit_limit_avg_2_prior from base where credit_limit >= 7500), with_latest as (select s.id, s.name, s.city, s.segment, s.is_active, s.credit_limit, s.age, s.credit_limit_int, s.is_active_label, s.corr_age_credit_limit, s.credit_limit_avg_2_prior, x.monthly_fee from metrics s left join lateral (select c.monthly_fee from subscriptions c where c.customer_id = s.id order by c.end_date desc, c.id desc limit 1) x on true), deduped as (select * from with_latest qualify row_number() over (partition by city order by age desc nulls last, id) = 1), latest_match as (select s.*, latest.status, latest.account_balance from deduped s join lateral (select c.status, c.balance as account_balance from accounts c where c.customer_id = s.id order by c.balance desc, c.id desc limit 1) latest on true), totals as (select status, count_if(city = 'Chiang Mai') as chiang_mai_events, stddev_samp(age) as age_stddev, bit_or(age) as age_bit_or, count_if(segment = 'Corporate') as corporate_events, count_if(segment = 'Consumer') as consumer_events from latest_match group by status) select status, chiang_mai_events, corporate_events, consumer_events, case when status rlike '^(FROZEN|CLOSED)$' then 'CORE' else 'OTHER_ZONE' end as status_zone from totals order by status desc
